Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

long long base[20];
int result;

long long get_first_digit(long long val, int &length) {
    length = 0;
    while (val >= 10) {
        val /= 10;
        length++;
    }
    return val;
}

void recurse(long long val, int steps) {
    if (steps >= result) return;
    if (val == 0) {
        result = steps;
        return;
    }
    int len;
    int first_digit = get_first_digit(val, len);
    recurse(abs(val - base[len] * first_digit), steps + first_digit * (len + 1));
    if (first_digit - 1 > 0)
        recurse(abs(val - base[len] * (first_digit - 1)), steps + (first_digit - 1) * (len + 1));
    if (first_digit > 1)
        recurse(abs(base[len + 1] - val), steps + (len + 2));
}

int main() {
    long long n;
    scanf("%lld", &n);
    base[0] = 1;
    for (int i = 1; i <= 18; i++) {
        base[i] = base[i - 1] * 10 + 1;
    }
    result = 1e9;
    recurse(n, 0);
    printf("%d\n", result);
    return 0;
}
